import { Auth } from "../route/auth.js";
import { AuthOptions } from "../route/auth-options.js";
import { MediaRoute } from "../route/media.js";
import { ProviderID } from "../schema/index.js";
import { ElevenLabsSpeech } from "../protocols/elevenlabs-speech.js";
import { ElevenLabsTranscription } from "../protocols/elevenlabs-transcription.js";
export const id = ProviderID.make("elevenlabs");
const auth = (options) => AuthOptions.apiKey(options, "ELEVENLABS_API_KEY", Auth.header("xi-api-key"));
export const configure = (input = {}) => {
    const media = MediaRoute.deployment(input, auth(input));
    const speech = (modelID) => ElevenLabsSpeech.model({ ...media, id: modelID });
    const transcription = (modelID) => ElevenLabsTranscription.model({ ...media, id: modelID });
    return {
        id,
        speech,
        transcription,
        configure,
    };
};
export const provider = configure();
export const speech = provider.speech;
export const transcription = provider.transcription;
